-- Executable observations and all-field gates for frozen cumulative Stage 1 + Stage 2 acceptance.
\set ON_ERROR_STOP on
SET TIME ZONE 'UTC';
\pset format unaligned
\pset null 'NULL'
CREATE OR REPLACE FUNCTION s2_setup(c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN TRUNCATE maintenance_request; INSERT INTO equipment(equipment_id,status) VALUES ('eq-stage1-known','available'),('eq-stage1-other','available') ON CONFLICT(equipment_id) DO UPDATE SET status=EXCLUDED.status; IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION '% setup failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_base(c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM report_equipment_fault('req-stage2-base','eq-stage1-known','reporter-stage1','2030-01-15T10:30:00Z','Hydraulic pressure warning observed'); IF (SELECT count(*) FROM maintenance_request m WHERE m.request_id='req-stage2-base' AND m.equipment_id='eq-stage1-known' AND m.reported_by='reporter-stage1' AND m.reported_at='2030-01-15T10:30:00Z'::timestamptz AND m.description='Hydraulic pressure warning observed' AND m.status='open' AND m.scheduled_for IS NULL AND m.completed_at IS NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION '% base failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_reject_schedule(a text,r text,s timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM schedule_maintenance(a,r,s); RAISE EXCEPTION 'unexpected schedule acceptance'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected schedule acceptance' THEN RAISE; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_reject_complete(a text,r text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN PERFORM complete_maintenance(a,r); RAISE EXCEPTION 'unexpected completion acceptance'; EXCEPTION WHEN OTHERS THEN IF SQLERRM='unexpected completion acceptance' THEN RAISE; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_open(c text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM maintenance_request m WHERE m.request_id='req-stage2-base' AND m.equipment_id='eq-stage1-known' AND m.reported_by='reporter-stage1' AND m.reported_at='2030-01-15T10:30:00Z'::timestamptz AND m.description='Hydraulic pressure warning observed' AND m.status='open' AND m.scheduled_for IS NULL AND m.completed_at IS NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION '% open assertion failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_scheduled(c text,s timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM maintenance_request m WHERE m.request_id='req-stage2-base' AND m.equipment_id='eq-stage1-known' AND m.reported_by='reporter-stage1' AND m.reported_at='2030-01-15T10:30:00Z'::timestamptz AND m.description='Hydraulic pressure warning observed' AND m.status='scheduled' AND m.scheduled_for=s AND m.completed_at IS NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION '% scheduled assertion failed',c; END IF; END $$;
CREATE OR REPLACE FUNCTION s2_completed(c text,s timestamptz) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF (SELECT count(*) FROM maintenance_request m WHERE m.request_id='req-stage2-base' AND m.equipment_id='eq-stage1-known' AND m.reported_by='reporter-stage1' AND m.reported_at='2030-01-15T10:30:00Z'::timestamptz AND m.description='Hydraulic pressure warning observed' AND m.status='completed' AND m.scheduled_for=s AND m.completed_at IS NOT NULL)<>1 OR (SELECT count(*) FROM maintenance_request)<>1 THEN RAISE EXCEPTION '% completed assertion failed',c; END IF; END $$;
SELECT to_char((clock_timestamp()+interval '48 hours') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') future_schedule_time, to_char((clock_timestamp()-interval '48 hours') AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') past_schedule_time \gset
SELECT 'authorization_fixture' observation,actor_evidence,role_name FROM stage2_authorization_fixture ORDER BY role_name;
-- S2-01
SELECT s2_setup('S2-01'); SELECT 'S2-01 report' observation,'reporter' actor,'req-stage2-base' request_id,'accepted' outcome,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') call_time; SELECT s2_base('S2-01'); SELECT 'S2-01 schedule input' observation,'stage2-coordinator-fixture' actor,'maintenance_coordinator fixture' authorization,'req-stage2-base' request_id,:'future_schedule_time' scheduled_for,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') call_start; SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'future_schedule_time'::timestamptz) accepted_request_id; SELECT 'S2-01 accepted' outcome,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') call_end; SELECT 'S2-01 row' observation,* FROM maintenance_request; SELECT s2_scheduled('S2-01',:'future_schedule_time'::timestamptz);
-- S2-02
SELECT s2_setup('S2-02'); SELECT s2_base('S2-02'); SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'future_schedule_time'::timestamptz); SELECT s2_scheduled('S2-02 prerequisite',:'future_schedule_time'::timestamptz); SELECT 'S2-02 complete input' observation,'stage2-technician-fixture' actor,'technician fixture' authorization,'req-stage2-base' request_id,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') call_start; SELECT complete_maintenance('stage2-technician-fixture','req-stage2-base') accepted_request_id; SELECT 'S2-02 accepted' outcome,to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') call_end; SELECT 'S2-02 row' observation,* FROM maintenance_request; SELECT s2_completed('S2-02',:'future_schedule_time'::timestamptz);
-- S2-03
SELECT s2_setup('S2-03'); SELECT s2_base('S2-03'); SELECT 'S2-03 before' observation,* FROM maintenance_request; SELECT s2_reject_complete('stage2-technician-fixture','req-stage2-base'); SELECT 'S2-03 rejected' outcome,'stage2-technician-fixture' actor; SELECT 'S2-03 after' observation,* FROM maintenance_request; SELECT s2_open('S2-03');
-- S2-04
SELECT s2_setup('S2-04'); SELECT s2_base('S2-04'); SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'future_schedule_time'::timestamptz); SELECT complete_maintenance('stage2-technician-fixture','req-stage2-base'); SELECT 'S2-04 before' observation,* FROM maintenance_request; SELECT s2_reject_schedule('stage2-coordinator-fixture','req-stage2-base',(clock_timestamp()+interval '72 hours')); SELECT 'S2-04 rejected' outcome,'stage2-coordinator-fixture' actor; SELECT 'S2-04 after' observation,* FROM maintenance_request; SELECT s2_completed('S2-04',:'future_schedule_time'::timestamptz);
-- S2-05 through S2-07
SELECT s2_setup('S2-05'); SELECT s2_base('S2-05'); SELECT 'S2-05 before' observation,* FROM maintenance_request; SELECT s2_reject_schedule('stage2-coordinator-fixture','req-stage2-base',:'past_schedule_time'::timestamptz); SELECT 'S2-05 rejected' outcome,:'past_schedule_time' attempted_schedule; SELECT 'S2-05 after' observation,* FROM maintenance_request; SELECT s2_open('S2-05');
SELECT s2_setup('S2-06'); SELECT s2_base('S2-06'); SELECT 'S2-06 before' observation,* FROM maintenance_request; SELECT s2_reject_schedule('reporter-stage1','req-stage2-base',:'future_schedule_time'::timestamptz); SELECT 'S2-06 rejected' outcome,'reporter-stage1' actor,'absent from authorization fixture' authorization; SELECT 'S2-06 after' observation,* FROM maintenance_request; SELECT s2_open('S2-06');
SELECT s2_setup('S2-07'); SELECT s2_base('S2-07'); SELECT schedule_maintenance('stage2-coordinator-fixture','req-stage2-base',:'future_schedule_time'::timestamptz); SELECT 'S2-07 before' observation,* FROM maintenance_request; SELECT s2_reject_complete('reporter-stage1','req-stage2-base'); SELECT 'S2-07 rejected' outcome,'reporter-stage1' actor,'absent from authorization fixture' authorization; SELECT 'S2-07 after' observation,* FROM maintenance_request; SELECT s2_scheduled('S2-07',:'future_schedule_time'::timestamptz);
-- S2-08 and S2-09
SELECT s2_setup('S2-08'); SELECT s2_reject_schedule('stage2-coordinator-fixture','req-stage2-missing',:'future_schedule_time'::timestamptz); SELECT 'S2-08 counts' observation,count(*) total,count(*) FILTER (WHERE request_id='req-stage2-missing') missing_id FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S2-08 failed'; END IF; END $$;
SELECT s2_setup('S2-09'); SELECT s2_reject_complete('stage2-technician-fixture','req-stage2-missing'); SELECT 'S2-09 counts' observation,count(*) total,count(*) FILTER (WHERE request_id='req-stage2-missing') missing_id FROM maintenance_request; DO $$ BEGIN IF (SELECT count(*) FROM maintenance_request)<>0 THEN RAISE EXCEPTION 'S2-09 failed'; END IF; END $$;
SELECT 'STAGE2_CUMULATIVE_ACCEPTANCE_PASS' result,current_database() database_name,current_schema() schema_name;
